type WiringZonesRow struct {
	PlanID    uuid.UUID
	ID        uuid.UUID
	Name      string
	ShortName string
}

func (q *Queries) WiringZones(ctx context.Context, versionID uuid.UUID) ([]WiringZonesRow, error) {
	rows, err := q.db.Query(ctx, wiringZones, versionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WiringZonesRow{}
	for rows.Next() {
		var i WiringZonesRow
		if err := rows.Scan(
			&i.PlanID,
			&i.ID,
			&i.Name,
			&i.ShortName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const zoneNames = `-- name: ZoneNames :many
SELECT z.plan_id, z.id, z.name, z.short_name
FROM plan_zones z JOIN plans p ON p.id = z.plan_id
WHERE p.version_id = $1
ORDER BY p.position, z.plan_id, z.position
`

type ZoneNamesRow struct {
	PlanID    uuid.UUID
	ID        uuid.UUID
	Name      string
	ShortName string
}

// ZoneNames: every zone of a version's floorplans with its short name
// (channel labels, 3e).
func (q *Queries) ZoneNames(ctx context.Context, versionID uuid.UUID) ([]ZoneNamesRow, error) {
	rows, err := q.db.Query(ctx, zoneNames, versionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ZoneNamesRow{}
	for rows.Next() {
		var i ZoneNamesRow
		if err := rows.Scan(
			&i.PlanID,
			&i.ID,
			&i.Name,
			&i.ShortName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
